Se reemplaza la secuencia de double-bridges aleatorios, que pueden anularse entre sí, por un único double-bridge generalizado. Se cortan 3·k puntos distintos del tour y se reordenan los segmentos sin conservar ninguna adyacencia original. Así el número de aristas rotas crece de forma monótona con `strength`.

```python
def _reorder_segments(m, rng, tries=50):
    rest = list(range(1, m))
    for _ in range(tries):
        rng.shuffle(rest)
        order = [0] + rest
        if all(order[i + 1] != order[i] + 1 for i in range(len(order) - 1)):
            return order
    if m >= 3:
        return [0] + list(range(m - 1, 0, -1))
    return [0] + rest


class MultiDoubleBridgeTour:
    def perturb(self, sol, strength: float, rng: Random):
        orig = list(sol)
        n = len(orig)
        if n < 2:
            return canonical(tuple(orig))
        k = max(1, int(round(strength))) * self.bps
        if n >= 4:
            c = min(n - 1, 3 * k)
            cuts = sorted(rng.sample(range(1, n), c))
            bounds = [0] + cuts + [n]
            segs = [orig[bounds[i]:bounds[i + 1]] for i in range(len(bounds) - 1)]
            order = _reorder_segments(len(segs), rng)
            t = []
            for idx in order:
                t.extend(segs[idx])
        else:
            t = list(orig)
            for _ in range(k):
                t = _fallback_swap(t, rng)
        if t == orig:
            t = _fallback_swap(orig, rng)
        return canonical(tuple(t))
